program.compute:
pool = read('/input/options')
result = None
for count in reversed(range(goal['min_count'], goal['max_count'] + 1)):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    write('/output/selection', result)
    selection = result
if receipt('report') == 'success':
    pass
else:
    if receipt('report') == 'unknown':
        if status('report') == 'not_sent':
            send('report', 'team', selection)
    else:
        if receipt('report') != 'failure':
            send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

